/**
 * The staff console's stylesheet, ported verbatim from the "Staff Console Redesign" artifact
 * (Dev2, 2026-11-14: "EXACTLY like the artifact"), generated by scoping every selector under
 * `.sc`, the element the console mounts in: `:root`, `html` and `body` became `.sc` itself, so
 * the console's class names (shared with the Lab: .app, .bar, .side) never reach another page.
 * The first rule makes the root fill the window the way the artifact's document did.
 */
export const CONSOLE_CSS = String.raw`.sc{position:fixed;inset:0;overflow:hidden}
/* Layout: the Context shell from the Lab (context.lc/lab). Top bar with modes; tree sidebar of pages; one work surface; a properties panel on the right for whatever row is open. Tokens are the app's own. */
.sc{
  --chrome:#F4F1EA; --page:#FFFDF9; --s2:#F7F4ED; --s3:#F0ECE3; --chip:rgba(26,23,20,0.05); --row:#E6E1D6; --sel:#FFFDF9; --track:#CFC8BB;
  --line:rgba(26,23,20,0.09); --line2:rgba(26,23,20,0.18);
  --text:#1A1714; --text2:#4A443C; --muted:#5E574D; --dim:#6B6356;
  --accent:#2A45CF; --accent-dim:rgba(42,69,207,0.10); --team:#6A46B8;
  --ok:#3E7A4E; --ok-wash:rgba(62,122,78,0.10); --warn:#96600A; --warn-wash:rgba(150,96,10,0.12); --bad:#B23A32; --bad-wash:rgba(178,58,50,0.10);
  --c1:#2A45CF; --c2:#2F8F83; --c3:#B4527F; --c4:#96600A; --c5:#6A46B8; --c6:#8A8274;
  --shadow:0 1px 2px rgba(26,23,20,.06),0 8px 24px rgba(26,23,20,.08); --scrim:rgba(26,23,20,.28);
  --f:"Instrument Sans",ui-sans-serif,system-ui,-apple-system,sans-serif; --mono:"JetBrains Mono",ui-monospace,Menlo,monospace;
}
@media (prefers-color-scheme: dark){.sc:not([data-theme="light"]){
  --chrome:#191715; --page:#201E1B; --s2:#282522; --s3:#2B2825; --chip:rgba(237,232,224,0.06); --row:#302C28; --sel:#3A3631; --track:#4D4842;
  --line:rgba(237,232,224,0.08); --line2:rgba(237,232,224,0.16);
  --text:#EDE8E0; --text2:#C3BCB2; --muted:#A79F95; --dim:#958D83;
  --accent:#8A9BF2; --accent-dim:rgba(138,155,242,0.15); --team:#B9A3F2;
  --ok:#82C98E; --ok-wash:rgba(130,201,142,0.12); --warn:#DFAC52; --warn-wash:rgba(223,172,82,0.12); --bad:#E5847D; --bad-wash:rgba(229,132,125,0.14);
  --c1:#8A9BF2; --c2:#5CC7B8; --c3:#E58AB4; --c4:#DFAC52; --c5:#B9A3F2; --c6:#A79F95;
  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.35); --scrim:rgba(0,0,0,.5); color-scheme:dark}}
.sc[data-theme="dark"]{
  --chrome:#191715; --page:#201E1B; --s2:#282522; --s3:#2B2825; --chip:rgba(237,232,224,0.06); --row:#302C28; --sel:#3A3631; --track:#4D4842;
  --line:rgba(237,232,224,0.08); --line2:rgba(237,232,224,0.16);
  --text:#EDE8E0; --text2:#C3BCB2; --muted:#A79F95; --dim:#958D83;
  --accent:#8A9BF2; --accent-dim:rgba(138,155,242,0.15); --team:#B9A3F2;
  --ok:#82C98E; --ok-wash:rgba(130,201,142,0.12); --warn:#DFAC52; --warn-wash:rgba(223,172,82,0.12); --bad:#E5847D; --bad-wash:rgba(229,132,125,0.14);
  --c1:#8A9BF2; --c2:#5CC7B8; --c3:#E58AB4; --c4:#DFAC52; --c5:#B9A3F2; --c6:#A79F95;
  --shadow:0 1px 2px rgba(0,0,0,.3),0 8px 24px rgba(0,0,0,.35); --scrim:rgba(0,0,0,.5); color-scheme:dark}
.sc *{box-sizing:border-box}
.sc,.sc{height:100%}
.sc{margin:0;background:var(--chrome);color:var(--text);font-family:var(--f);font-size:14px;line-height:1.4;overflow:hidden}
.sc button,.sc select,.sc input,.sc textarea{font:inherit;color:inherit}
.sc button{cursor:pointer}
.sc a{color:var(--accent);text-decoration:none}.sc a:hover{text-decoration:underline}
.sc :focus-visible{outline:2px solid var(--accent);outline-offset:2px}
.sc .pop{position:relative;display:inline-block}.sc .pop>.pb{display:none;position:absolute;right:0;top:calc(100% + 4px);z-index:30;min-width:200px;background:var(--page);border:1px solid var(--line);border-radius:10px;box-shadow:0 8px 24px rgba(0,0,0,.14);padding:8px 10px;text-align:left;flex-direction:column;gap:4px;font-size:13px;white-space:nowrap}.sc .pop:hover>.pb,.sc .pop:focus-within>.pb{display:flex}.sc .pb .pr{display:flex;justify-content:space-between;gap:14px}
.sc .ponly{display:none}@media (max-width:820px){.sc .ponly{display:block}.sc td.acts button{display:block;width:100%;margin:2px 0}}
.sc mark{background:var(--warn-wash);color:inherit;border-radius:3px}
.sc svg.i{width:18px;height:18px;flex:none;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.sc .app{height:100%;display:grid;grid-template-rows:56px minmax(0,1fr);padding-left:env(safe-area-inset-left,0px);padding-right:env(safe-area-inset-right,0px)}
.sc .bar{display:flex;align-items:center;gap:8px;padding:0 12px;min-width:0}
.sc .ib{display:inline-grid;place-items:center;width:36px;height:36px;border-radius:9px;border:1px solid var(--line);background:var(--page);color:var(--text2);padding:0;flex:none}
.sc .ib:hover{background:var(--s3)}
.sc .ib.sm{width:28px;height:28px;border-radius:7px}
.sc .modes{display:inline-flex;background:var(--s3);border-radius:10px;padding:3px;gap:2px;flex:none}
.sc .modes a,.sc .modes button{border:none;background:none;font-weight:600;font-size:13px;color:var(--muted);padding:5px 11px;border-radius:8px;text-decoration:none;display:inline-flex;align-items:center;gap:4px}
.sc .modes [aria-current=true]{background:var(--sel);color:var(--text);box-shadow:0 0 0 1px var(--line2)}
.sc .modes a:hover{color:var(--text)}
.sc .crumb{font-weight:600;font-size:15px;white-space:nowrap;overflow:hidden;min-width:0;display:flex;gap:4px;align-items:center}
.sc .crumb button{border:none;background:none;padding:2px 4px;border-radius:6px;color:var(--muted);font-weight:500;overflow:hidden;text-overflow:ellipsis;min-width:0}
.sc .crumb button:last-child,.sc .crumb span:last-child{color:var(--text);font-weight:600}
.sc .crumb button:hover{background:var(--chip);color:var(--text)}
.sc .crumb .sep{color:var(--dim);font-weight:400;flex:none}
.sc .spacer{flex:1}
.sc .seg{display:inline-flex;gap:2px;background:var(--chip);border-radius:9px;padding:3px;max-width:100%;overflow-x:auto;scrollbar-width:none;flex:none}
.sc .seg::-webkit-scrollbar{display:none}
.sc .seg button{border:none;background:none;border-radius:7px;padding:5px 10px;font-size:12.5px;color:var(--muted);display:inline-flex;align-items:center;gap:6px;white-space:nowrap;flex:none}
.sc .seg button:hover{color:var(--text)}
.sc .seg button[aria-pressed=true]{background:var(--sel);color:var(--text);box-shadow:0 0 0 1px var(--line2)}
.sc .seg .n{font-size:11.5px;color:var(--dim);font-variant-numeric:tabular-nums}
.sc .thm{display:inline-flex;gap:2px;padding:2px;border:1px solid var(--line);border-radius:8px;background:var(--chip);flex:none}
.sc .thm button{display:grid;place-items:center;width:26px;height:24px;padding:0;border:none;border-radius:6px;background:none;color:var(--dim)}
.sc .thm button:hover{color:var(--text)}
.sc .thm button[aria-checked=true]{background:var(--sel);color:var(--text);box-shadow:0 0 0 1px var(--line2)}
.sc .thm svg.i{width:15px;height:15px}
.sc .body{display:grid;grid-template-columns:240px minmax(0,1fr);min-height:0}
.sc .body.props{grid-template-columns:240px minmax(0,1fr) 360px}
.sc .body.noside{grid-template-columns:minmax(0,1fr)}
.sc .body.noside.props{grid-template-columns:minmax(0,1fr) 360px}
.sc .side{overflow:auto;padding:6px 8px 16px;min-height:0}
.sc .sec{font-size:11.5px;color:var(--dim);padding:14px 10px 4px;letter-spacing:.02em}
.sc .rowi{display:flex;align-items:center;gap:10px;width:100%;padding:7px 10px;border-radius:9px;border:none;background:none;color:var(--text);text-align:left;font-size:14px;min-width:0}
.sc .rowi:hover{background:var(--chip);text-decoration:none}
.sc .rowi[aria-current=true]{background:var(--row)}
.sc .rowi .nm{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sc .rowi .ct{font-size:11.5px;font-variant-numeric:tabular-nums;color:var(--dim)}
.sc .rowi .ct.hot{color:var(--warn);background:var(--warn-wash);border-radius:999px;padding:1px 7px}
.sc .rowi .ct.mock{color:var(--team)}
.sc .rowi svg.i{color:var(--muted)}
.sc .main{background:var(--page);border-top-left-radius:12px;min-width:0;min-height:0;position:relative;overflow:hidden;border-left:1px solid var(--line);border-top:1px solid var(--line)}
.sc .body.props .main{border-top-right-radius:12px;border-right:1px solid var(--line)}
.sc .body.noside .main{border-top-left-radius:0;border-left:none}
.sc .pg{position:absolute;inset:0;overflow:auto}
.sc .pgin{max-width:1080px;margin:0 auto;padding:20px 24px 72px;display:flex;flex-direction:column;gap:14px}
.sc .tools{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
.sc .search{border:1px solid var(--line);background:var(--page);border-radius:9px;padding:7px 10px;min-width:0;flex:1 1 180px;max-width:300px}
.sc .ghost{height:32px;padding:0 11px;border-radius:8px;border:1px solid var(--line);background:var(--page);color:var(--text2);display:inline-flex;align-items:center;gap:6px;white-space:nowrap;font-size:13px;text-decoration:none!important}
.sc .ghost:hover{background:var(--s3)}
.sc .ghost.danger{color:var(--bad)}
.sc .ghost:disabled{opacity:.45;cursor:default}
.sc .primary{height:32px;padding:0 13px;border-radius:8px;border:none;background:var(--accent);color:var(--page);font-weight:600;font-size:13px;white-space:nowrap}
.sc .primary.danger{background:var(--bad)}
.sc .primary:disabled{opacity:.45;cursor:default}
.sc td .ghost,.sc td .primary{height:26px;padding:0 9px;font-size:12.5px}
.sc .link{border:none;background:none;padding:0;color:var(--accent);font-size:13px;text-align:left}
.sc .link:hover{text-decoration:underline}
.sc .kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px}
.sc .kpi{border:1px solid var(--line);border-radius:12px;padding:11px 13px;background:var(--page);min-width:0;text-align:left;display:flex;flex-direction:column}
.sc button.kpi{cursor:pointer;border-color:var(--line2)}.sc button.kpi:hover{background:var(--s2)}
.sc button.kpi[aria-pressed=true]{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}
.sc .kpi .l{font-size:12.5px;color:var(--muted);display:flex;align-items:center;gap:6px}
.sc .kpi .l svg{width:14px;height:14px;margin-left:auto;color:var(--dim)}
.sc .kpi .v{font-size:24px;font-weight:600;font-variant-numeric:tabular-nums;margin:1px 0;letter-spacing:-.01em}
.sc .kpi .d{font-size:12px;color:var(--dim);font-variant-numeric:tabular-nums}
.sc .kpi .sp{margin-top:6px}
.sc .up{color:var(--ok)}.sc .dn{color:var(--bad)}
.sc .pn{border:1px solid var(--line);border-radius:12px;background:var(--page);min-width:0}
.sc .pnh{display:flex;align-items:center;gap:8px;padding:8px 12px;min-height:44px;flex-wrap:wrap}
.sc .pnh .tg{display:flex;align-items:center;gap:6px;border:none;background:none;padding:2px 4px 2px 0;font-weight:600;font-size:14px;color:var(--text);text-align:left;min-width:0}
.sc .pnh .tg .car{width:14px;height:14px;color:var(--dim);transition:transform .15s}
.sc .pn.shut .pnh .tg .car{transform:rotate(-90deg)}
.sc .pnh .meta{font-size:12.5px;color:var(--dim);font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0}
.sc .pnh .acts{margin-left:auto;display:flex;gap:6px;align-items:center;flex-wrap:wrap;justify-content:flex-end}
.sc .pnb{padding:0 12px 12px;min-width:0}
.sc .pn.shut .pnb{display:none}
.sc .tbl{overflow-x:auto;min-width:0}
.sc table{border-collapse:collapse;width:100%;font-variant-numeric:tabular-nums;font-size:13.5px}
.sc th,.sc td{text-align:left;padding:0 8px;height:44px;border-bottom:1px solid var(--line);vertical-align:middle;white-space:nowrap}
.sc td.wrap{white-space:normal;min-width:200px;padding-block:8px}
.sc tr:last-child td{border-bottom:none}
.sc th{font-size:12px;color:var(--dim);font-weight:500;height:34px}
.sc th.r,.sc td.r{text-align:right}
.sc th button{border:none;background:none;padding:0;color:inherit;font:inherit;display:inline-flex;gap:3px;align-items:center}
.sc th button:hover{color:var(--text)}
.sc tr.click{cursor:pointer}
.sc tr.click:hover td,.sc tr.click:focus-visible td{background:var(--s2)}
.sc tr.click:focus-visible{outline:2px solid var(--accent);outline-offset:-2px}
.sc tr[aria-selected=true] td{background:var(--accent-dim)}
.sc .sub{font-size:12px;color:var(--dim)}
.sc .mono{font-family:var(--mono);font-size:12px}
.sc .pill{display:inline-flex;align-items:center;gap:4px;border-radius:999px;padding:1px 8px;font-size:12px;background:var(--chip);color:var(--text2);white-space:nowrap;border:none}
.sc button.pill{cursor:pointer}.sc button.pill:hover{text-decoration:underline}
.sc .pill.ok{background:var(--ok-wash);color:var(--ok)}.sc .pill.warn{background:var(--warn-wash);color:var(--warn)}.sc .pill.bad{background:var(--bad-wash);color:var(--bad)}.sc .pill.acc{background:var(--accent-dim);color:var(--accent)}.sc .pill.team{background:color-mix(in srgb,var(--team) 14%,transparent);color:var(--team)}
.sc .sw{position:relative;width:34px;height:20px;border-radius:999px;border:none;background:var(--track);padding:0;flex:none;transition:background .15s}
.sc .sw::after{content:"";position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:#FFFDF9;box-shadow:0 1px 2px rgba(0,0,0,.25);transition:left .15s}
.sc .sw[aria-checked=true]{background:var(--accent)}
.sc .sw[aria-checked=true]::after{left:16px}
.sc .needs{display:flex;flex-direction:column}
.sc .need{display:flex;align-items:center;gap:12px;padding:10px 4px;border:none;border-bottom:1px solid var(--line);background:none;text-align:left;width:100%;border-radius:0;min-height:44px}
.sc .need:last-child{border-bottom:none}
.sc button.need:hover{background:var(--s2)}
.sc .need .dt{width:8px;height:8px;border-radius:50%;flex:none}
.sc .need .tx{flex:1;min-width:0}
.sc .need .tx b{font-weight:600}
.sc .need .where{font-size:12.5px;color:var(--dim);white-space:nowrap}
.sc .need svg.i{width:16px;height:16px;color:var(--dim)}
.sc .chart{width:100%;height:auto;display:block;overflow:visible}
.sc .chart text{fill:var(--dim);font-family:var(--f)}
.sc .chart .grid{stroke:var(--line);stroke-width:1}
.sc .legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:12px;color:var(--muted);padding-top:6px}
.sc .legend span{display:inline-flex;align-items:center;gap:6px}
.sc .legend i{width:10px;height:10px;border-radius:3px;display:inline-block}
.sc .lgt{border:none;background:none;padding:2px 0;font-size:12px;color:var(--dim);display:inline-flex;align-items:center;gap:4px;margin-top:4px}
.sc .lgt .car{width:12px;height:12px;transition:transform .15s}
.sc .lgt[aria-expanded=false] .car{transform:rotate(-90deg)}
.sc .grid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(320px,1fr));gap:14px;align-items:start}
.sc .fun{display:flex;flex-direction:column;gap:6px}
.sc .fun .r{display:grid;grid-template-columns:minmax(110px,170px) minmax(0,1fr) 92px;gap:10px;align-items:center;font-size:13px}
.sc .fun .tr{height:16px;background:var(--chip);border-radius:4px;position:relative}
.sc .fun .bb{position:absolute;inset:0 auto 0 0;border-radius:4px;background:var(--accent)}
.sc .fun .t{text-align:right;color:var(--muted);font-variant-numeric:tabular-nums}
.sc .share{display:flex;height:10px;border-radius:5px;overflow:hidden;background:var(--chip)}
.sc .share i{display:block;height:100%}
.sc .facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px 18px;margin-top:10px}
.sc .facts .l{font-size:12px;color:var(--dim)}.sc .facts .v{font-weight:600;font-variant-numeric:tabular-nums}
.sc .bulk{display:flex;align-items:center;gap:8px;flex-wrap:wrap;background:var(--accent-dim);border-radius:10px;padding:6px 10px;font-size:13px}
.sc .banner{display:flex;align-items:center;gap:10px;flex-wrap:wrap;border-radius:10px;padding:8px 12px;font-size:13.5px;background:var(--warn-wash)}
.sc .banner.ok{background:var(--ok-wash)}
.sc .banner .tx{flex:1;min-width:0}
.sc .props-pane{overflow:auto;min-height:0;padding:12px 14px 40px;background:var(--chrome);position:relative}
.sc .handle{display:none}
.sc .pp{display:flex;flex-direction:column;gap:12px}
.sc .pph{display:flex;align-items:flex-start;gap:8px}
.sc .pph h3{margin:0;font-size:17px;font-weight:600;flex:1;min-width:0;overflow-wrap:anywhere;outline:none}
.sc .ppb{border:1px solid var(--line);border-radius:12px;background:var(--page);padding:10px 12px;display:flex;flex-direction:column;gap:8px}
.sc .ppb .h{font-size:12px;color:var(--dim)}
.sc .kv{display:grid;grid-template-columns:auto minmax(0,1fr);gap:6px 12px;font-size:13px}
.sc .kv .k{color:var(--dim)}
.sc .kv .v{overflow-wrap:anywhere;font-variant-numeric:tabular-nums}
.sc .av{width:30px;height:30px;border-radius:50%;display:grid;place-items:center;background:var(--accent-dim);color:var(--accent);font-weight:600;flex:none;font-size:13px}
.sc .who{display:flex;align-items:center;gap:10px;min-width:0}
.sc .who .nm{font-weight:500;overflow:hidden;text-overflow:ellipsis}
.sc .wf{display:flex;flex-direction:column;gap:4px}
.sc .wf .r{display:grid;grid-template-columns:minmax(80px,120px) minmax(0,1fr) 50px;gap:8px;align-items:center;font-size:12.5px}
.sc .wf .tr{position:relative;height:12px;background:var(--chip);border-radius:3px}
.sc .wf .bb{position:absolute;top:0;height:12px;border-radius:3px}
.sc .wf .t{text-align:right;color:var(--muted);font-variant-numeric:tabular-nums}
.sc .wf .slow .bb{outline:2px solid var(--warn);outline-offset:1px}
.sc .wf .slow span:first-child{font-weight:600}
.sc .field{display:flex;flex-direction:column;gap:4px;font-size:12.5px;color:var(--dim)}
.sc .field input,.sc .field textarea,.sc .field select{border:1px solid var(--line);background:var(--page);border-radius:8px;padding:7px 9px;color:var(--text);font-size:13.5px;width:100%}
.sc .field textarea{resize:vertical;min-height:70px}
.sc textarea.code{font-family:var(--mono);font-size:12px;min-height:220px}
.sc .row{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.sc .chips{display:flex;flex-wrap:wrap;gap:6px;align-items:center}
.sc .chipx{display:inline-flex;align-items:center;gap:5px;border:1px solid var(--line);border-radius:999px;padding:2px 4px 2px 9px;font-size:12.5px;background:var(--page)}
.sc .chipx button{border:none;background:none;padding:0 4px;color:var(--dim);border-radius:50%}
.sc .chipx button:hover{color:var(--bad)}
.sc .card{border:1px solid var(--line);border-radius:12px;background:var(--page);padding:11px 13px;display:flex;flex-direction:column;gap:6px;text-align:left;width:100%}
.sc button.card:hover{border-color:var(--line2);background:var(--s2)}
.sc .card[aria-selected=true]{border-color:var(--accent);box-shadow:0 0 0 1px var(--accent)}
.sc .card .t{font-weight:600}
.sc .list{display:flex;flex-direction:column;gap:8px}
.sc .bub{max-width:88%;background:var(--s3);border-radius:14px 14px 14px 4px;padding:7px 10px;font-size:13px;overflow-wrap:anywhere;align-self:flex-start}
.sc .bub.tex{align-self:flex-end;background:var(--accent-dim);border-radius:14px 14px 4px 14px}
.sc .thr{display:flex;flex-direction:column;gap:6px}
.sc .chg{display:grid;grid-template-columns:76px minmax(0,1fr);gap:2px 14px;padding:10px 0;border-bottom:1px solid var(--line);font-size:13.5px}
.sc .chg:last-child{border-bottom:none}
.sc .chg .what{font-weight:600}
.sc .chg .why{color:var(--muted);grid-column:2}
.sc .chg .tag{grid-row:span 2}
.sc .empty{padding:22px;text-align:center;color:var(--dim);font-size:13px}
.sc .confirm{display:inline-flex;gap:6px;align-items:center;flex-wrap:wrap;font-size:12.5px;color:var(--text2)}
.sc .toast{position:fixed;left:50%;transform:translateX(-50%);bottom:calc(20px + env(safe-area-inset-bottom,0px));background:var(--text);color:var(--page);padding:8px 10px 8px 14px;border-radius:9px;font-size:13px;z-index:40;max-width:90vw;box-shadow:var(--shadow);display:flex;gap:12px;align-items:center}
.sc .toast button{border:none;background:none;color:var(--page);font-weight:600;text-decoration:underline;padding:2px 4px}
.sc .scrim,.sc .pscrim{display:none}
.sc .tl{display:flex;flex-direction:column}
.sc .tl .it{display:grid;grid-template-columns:62px minmax(0,1fr) auto;gap:10px;align-items:center;padding:8px 0;border-bottom:1px solid var(--line);font-size:13.5px}
.sc .tl .it:last-child{border-bottom:none}
.sc .tgt{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px}
.sc .tgt .g{border:1px solid var(--line);border-radius:10px;padding:9px 11px}
.sc .tgt .g .l{font-size:12px;color:var(--dim)}
.sc .tgt .g .v{font-size:19px;font-weight:600;font-variant-numeric:tabular-nums}
.sc .tgt .meter{height:6px;border-radius:3px;background:var(--chip);position:relative;margin-top:6px}
.sc .tgt .meter i{position:absolute;inset:0 auto 0 0;border-radius:3px}
.sc .tgt .meter b{position:absolute;top:-3px;width:2px;height:12px;background:var(--text2)}
.sc .rl{display:flex;flex-direction:column;gap:10px;font-size:13.5px}
.sc .rl h4{margin:0 0 4px;font-size:13px}
.sc .rl ul{margin:0;padding-left:18px;color:var(--muted)}
@media (max-width:1100px){.sc .body{grid-template-columns:210px minmax(0,1fr)}.sc .body.props{grid-template-columns:210px minmax(0,1fr) 320px}.sc .body.noside.props{grid-template-columns:minmax(0,1fr) 320px}}
@media (max-width:820px){
  .sc .body,.sc .body.props,.sc .body.noside,.sc .body.noside.props{grid-template-columns:minmax(0,1fr)}
  .sc .side{position:fixed;z-index:15;left:0;top:56px;bottom:0;width:min(280px,85vw);background:var(--chrome);box-shadow:var(--shadow);transform:translateX(-105%);transition:transform .2s;padding-left:max(8px,env(safe-area-inset-left,0px))}
  .sc .app.sideopen .side{transform:none}
  .sc .app.sideopen .scrim{display:block;position:fixed;inset:56px 0 0 0;z-index:14;background:var(--scrim)}
  .sc .side[hidden]{display:block!important}
  .sc .main{border-radius:0!important;border-left:none;border-right:none!important}
  .sc .props-pane{position:fixed;z-index:12;left:0;right:0;bottom:0;max-height:72%;border-top:1px solid var(--line2);border-radius:16px 16px 0 0;box-shadow:0 -8px 30px rgba(0,0,0,.25);padding-top:4px;padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px));padding-bottom:calc(24px + env(safe-area-inset-bottom,0px))}
  .sc .handle{display:block;width:40px;height:5px;border-radius:3px;background:var(--line2);margin:4px auto 10px;border:none;padding:0}
  .sc .pscrim.on{display:block;position:fixed;inset:0;z-index:11;background:var(--scrim)}
  .sc .pgin{padding:14px max(16px,env(safe-area-inset-left,0px)) 80px max(16px,env(safe-area-inset-right,0px))}
  .sc .bar{gap:6px;padding:0 10px}
  .sc .modes a,.sc .modes button{padding:5px 8px}
  .sc .modes .lbl{display:none}
  .sc .bar .winseg{display:none}
  .sc .winrow{display:flex!important}
  .sc .thm button[aria-checked=false]{display:none}
  .sc .kpis{grid-template-columns:1fr 1fr}
  .sc .kpis>*:last-child:nth-child(odd){grid-column:span 2}
  .sc .hp{display:none}
  .sc .chg{grid-template-columns:1fr}.sc .chg .why{grid-column:1}.sc .chg .tag{grid-row:auto}
  .sc .fun .r{grid-template-columns:minmax(90px,120px) minmax(0,1fr) 78px}
}
.sc .winrow{display:none}
@media (prefers-reduced-motion:reduce){.sc *{transition:none!important}}
`;
